  3610  // Returns 0 on success,
  3611  //        -1 on EOF,
  3612  //       <-1 on error
  3613  int sam_read1(htsFile *fp, sam_hdr_t *h, bam1_t *b)
  3614  {
  3615      int ret, pass_filter;
  3616
  3617      do {
  3618          switch (fp->format.format) {
  3619          case bam:
  3620              ret = sam_read1_bam(fp, h, b);
  3621              break;
  3622
  3623          case cram:
  3624              ret = sam_read1_cram(fp, h, &b);
  3625              break;
  3626
  3627          case sam:
  3628              ret = sam_read1_sam(fp, h, b);
  3629              break;
  3630
  3631          case empty_format:
  3632              errno = EPIPE;
  3633              return -3;
  3634
  3635          default:
  3636              errno = EFTYPE;
  3637              return -3;
  3638          }
  3639
  3640          pass_filter = (ret >= 0 && fp->filter)
  3641              ? sam_passes_filter(h, b, fp->filter)
  3642              : 1;
  3643      } while (pass_filter == 0);
  3644
  3645      return pass_filter < 0 ? -2 : ret;
  3646  }
