  3649  static int sam_format1_append(const bam_hdr_t *h, const bam1_t *b, kstring_t *str)
  3650  {
  3651      int i, r = 0;
  3652      uint8_t *s, *end;
  3653      const bam1_core_t *c = &b->core;
  3654
  3655      if (c->l_qname == 0)
  3656          return -1;
  3657      r |= kputsn_(bam_get_qname(b), c->l_qname-1-c->l_extranul, str);
  3658      r |= kputc_('\t', str); // query name
  3659      r |= kputw(c->flag, str); r |= kputc_('\t', str); // flag
  3660      if (c->tid >= 0) { // chr
  3661          r |= kputs(h->target_name[c->tid] , str);
  3662          r |= kputc_('\t', str);
  3663      } else r |= kputsn_("*\t", 2, str);
  3664      r |= kputll(c->pos + 1, str); r |= kputc_('\t', str); // pos
  3665      r |= kputw(c->qual, str); r |= kputc_('\t', str); // qual
  3666      if (c->n_cigar) { // cigar
  3667          uint32_t *cigar = bam_get_cigar(b);
  3668          for (i = 0; i < c->n_cigar; ++i) {
  3669              r |= kputw(bam_cigar_oplen(cigar[i]), str);
  3670              r |= kputc_(bam_cigar_opchr(cigar[i]), str);
  3671          }
  3672      } else r |= kputc_('*', str);
  3673      r |= kputc_('\t', str);
  3674      if (c->mtid < 0) r |= kputsn_("*\t", 2, str); // mate chr
  3675      else if (c->mtid == c->tid) r |= kputsn_("=\t", 2, str);
  3676      else {
  3677          r |= kputs(h->target_name[c->mtid], str);
  3678          r |= kputc_('\t', str);
  3679      }
  3680      r |= kputll(c->mpos + 1, str); r |= kputc_('\t', str); // mate pos
  3681      r |= kputll(c->isize, str); r |= kputc_('\t', str); // template len
  3682      if (c->l_qseq) { // seq and qual
  3683          uint8_t *s = bam_get_seq(b);
  3684          if (ks_resize(str, str->l+2+2*c->l_qseq) < 0) goto mem_err;
  3685          char *cp = str->s + str->l;
  3686
  3687          // Sequence, 2 bases at a time
  3688          nibble2base(s, cp, c->l_qseq);
  3689          cp[c->l_qseq] = '\t';
  3690          cp += c->l_qseq+1;
  3691
  3692          // Quality
  3693          s = bam_get_qual(b);
  3694          i = 0;
  3695          if (s[0] == 0xff) {
  3696              cp[i++] = '*';
  3697          } else {
  3698              // local copy of c->l_qseq to aid unrolling
  3699              uint32_t lqseq = c->l_qseq;
  3700              for (i = 0; i < lqseq; ++i)
  3701                  cp[i]=s[i]+33;
  3702          }
  3703          cp[i] = 0;
  3704          cp += i;
  3705          str->l = cp - str->s;
  3706      } else r |= kputsn_("*\t*", 3, str);
  3707
  3708      s = bam_get_aux(b); // aux
  3709      end = b->data + b->l_data;
  3710
  3711      while (end - s >= 4) {
  3712          r |= kputc_('\t', str);
  3713          if ((s = (uint8_t *)sam_format_aux1(s, s[2], s+3, end, str)) == NULL)
  3714              goto bad_aux;
  3715      }
  3716      r |= kputsn("", 0, str); // nul terminate
  3717      if (r < 0) goto mem_err;
  3718
  3719      return str->l;
  3720
  3721   bad_aux:
  3722      hts_log_error("Corrupted aux data for read %.*s",
  3723                    b->core.l_qname, bam_get_qname(b));
  3724      errno = EINVAL;
  3725      return -1;
  3726
  3727   mem_err:
  3728      hts_log_error("Out of memory");
  3729      errno = ENOMEM;
  3730      return -1;
  3731  }
