  3284  // Runs in its own thread.
  3285  // Takes encoded blocks of SAM off the thread results queue and writes them
  3286  // to our output stream.
  3287  static void *sam_dispatcher_write(void *vp) {
  3288      htsFile *fp = vp;
  3289      SAM_state *fd = fp->state;
  3290      hts_tpool_result *r;
  3291
  3292      // Iterates until result queue is shutdown, where it returns NULL.
  3293      while ((r = hts_tpool_next_result_wait(fd->q))) {
  3294          sp_lines *gl = (sp_lines *)hts_tpool_result_data(r);
  3295          if (!gl) {
  3296              sam_state_err(fd, ENOMEM);
  3297              goto err;
  3298          }
  3299
  3300          if (fp->idx) {
  3301              sp_bams *gb = gl->bams;
  3302              int i = 0, count = 0;
  3303              while (i < gl->data_size) {
  3304                  int j = i;
  3305                  while (i < gl->data_size && gl->data[i] != '\n')
  3306                      i++;
  3307                  if (i < gl->data_size)
  3308                      i++;
  3309
  3310                  if (fp->is_bgzf) {
  3311                      if (bgzf_write(fp->fp.bgzf, &gl->data[j], i-j) != i-j)
  3312                          goto err;
  3313                  } else {
  3314                      if (hwrite(fp->fp.hfile, &gl->data[j], i-j) != i-j)
  3315                          goto err;
  3316                  }
  3317
  3318                  bam1_t *b = &gb->bams[count++];
  3319                  if (fp->format.compression == bgzf) {
  3320                      if (bgzf_idx_push(fp->fp.bgzf, fp->idx,
  3321                                        b->core.tid, b->core.pos, bam_endpos(b),
  3322                                        bgzf_tell(fp->fp.bgzf),
  3323                                        !(b->core.flag&BAM_FUNMAP)) < 0) {
  3324                          sam_state_err(fd, errno ? errno : ENOMEM);
  3325                          hts_log_error("Read '%s' with ref_name='%s', ref_length=%"PRIhts_pos", flags=%d, pos=%"PRIhts_pos" cannot be indexed",
  3326                                  bam_get_qname(b), sam_hdr_tid2name(fd->h, b->core.tid), sam_hdr_tid2len(fd->h, b->core.tid), b->core.flag, b->core.pos+1);
  3327                          goto err;
  3328                      }
  3329                  } else {
  3330                      if (hts_idx_push(fp->idx, b->core.tid, b->core.pos, bam_endpos(b),
  3331                                       bgzf_tell(fp->fp.bgzf), !(b->core.flag&BAM_FUNMAP)) < 0) {
  3332                          sam_state_err(fd, errno ? errno : ENOMEM);
  3333                          hts_log_error("Read '%s' with ref_name='%s', ref_length=%"PRIhts_pos", flags=%d, pos=%"PRIhts_pos" cannot be indexed",
  3334                                  bam_get_qname(b), sam_hdr_tid2name(fd->h, b->core.tid), sam_hdr_tid2len(fd->h, b->core.tid), b->core.flag, b->core.pos+1);
  3335                          goto err;
  3336                      }
  3337                  }
  3338              }
  3339
  3340              assert(count == gb->nbams);
  3341
  3342              // Add bam array to free-list
  3343              pthread_mutex_lock(&fd->lines_m);
  3344              gb->next = fd->bams;
  3345              fd->bams = gl->bams;
  3346              gl->bams = NULL;
  3347              pthread_mutex_unlock(&fd->lines_m);
  3348          } else {
  3349              if (fp->is_bgzf) {
  3350                  if (bgzf_write(fp->fp.bgzf, gl->data, gl->data_size) != gl->data_size)
  3351                      goto err;
  3352              } else {
  3353                  if (hwrite(fp->fp.hfile, gl->data, gl->data_size) != gl->data_size)
  3354                      goto err;
  3355              }
  3356          }
  3357
  3358          hts_tpool_delete_result(r, 0);
  3359
  3360          // Also updated by main thread
  3361          pthread_mutex_lock(&fd->lines_m);
  3362          gl->next = fd->lines;
  3363          fd->lines = gl;
  3364          pthread_mutex_unlock(&fd->lines_m);
  3365      }
  3366
  3367      sam_state_err(fd, 0); // success
  3368      hts_tpool_process_shutdown(fd->q);
  3369      return NULL;
  3370
  3371   err:
  3372      sam_state_err(fd, errno ? errno : EIO);
  3373      return (void *)-1;
  3374  }
