   314  int hts_detect_format(hFILE *hfile, htsFormat *fmt)
   315  {
   316      char columns[24];
   317      unsigned char s[1024];
   318      int complete = 0;
   319      ssize_t len = hpeek(hfile, s, 18);
   320      if (len < 0) return -1;
   321
   322      fmt->category = unknown_category;
   323      fmt->format = unknown_format;
   324      fmt->version.major = fmt->version.minor = -1;
   325      fmt->compression = no_compression;
   326      fmt->compression_level = -1;
   327      fmt->specific = NULL;
   328
   329      if (len >= 2 && s[0] == 0x1f && s[1] == 0x8b) {
   330          // The stream is either gzip-compressed or BGZF-compressed.
   331          // Determine which, and decompress the first few records or lines.
   332          fmt->compression = (len >= 18 && (s[3] & 4) &&
   333                              memcmp(&s[12], "BC\2\0", 4) == 0)? bgzf : gzip;
   334          if (len >= 9 && s[2] == 8)
   335              fmt->compression_level = (s[8] == 2)? 9 : (s[8] == 4)? 1 : -1;
   336
   337          len = decompress_peek(hfile, s, sizeof s);
   338      }
   339      else if (len >= 10 && memcmp(s, "BZh", 3) == 0 &&
   340               (memcmp(&s[4], "\x31\x41\x59\x26\x53\x59", 6) == 0 ||
   341                memcmp(&s[4], "\x17\x72\x45\x38\x50\x90", 6) == 0)) {
   342          fmt->compression = bzip2_compression;
   343          fmt->compression_level = s[3] - '0';
   344          // Decompressing via libbz2 produces no output until it has a whole
   345          // block (of size 100Kb x level), which is too large for peeking.
   346          // So unfortunately we can recognise bzip2 but not the contents,
   347          // except that \x1772... magic indicates the stream is empty.
   348          if (s[4] == '\x31') return 0;
   349          else len = 0;
   350      }
   351      else {
   352          len = hpeek(hfile, s, sizeof s);
   353      }
   354      if (len < 0) return -1;
   355
   356      if (len == 0) {
   357          fmt->format = empty_format;
   358          return 0;
   359      }
   360
   361      if (len >= 6 && memcmp(s,"CRAM",4) == 0 && s[4]>=1 && s[4]<=7 && s[5]<=7) {
   362          fmt->category = sequence_data;
   363          fmt->format = cram;
   364          fmt->version.major = s[4], fmt->version.minor = s[5];
   365          fmt->compression = custom;
   366          return 0;
   367      }
   368      else if (len >= 4 && s[3] <= '\4') {
   369          if (memcmp(s, "BAM\1", 4) == 0) {
   370              fmt->category = sequence_data;
   371              fmt->format = bam;
   372              // TODO Decompress enough to pick version from @HD-VN header
   373              fmt->version.major = 1, fmt->version.minor = -1;
   374              return 0;
   375          }
   376          else if (memcmp(s, "BAI\1", 4) == 0) {
   377              fmt->category = index_file;
   378              fmt->format = bai;
   379              fmt->version.major = -1, fmt->version.minor = -1;
   380              return 0;
   381          }
   382          else if (memcmp(s, "BCF\4", 4) == 0) {
   383              fmt->category = variant_data;
   384              fmt->format = bcf;
   385              fmt->version.major = 1, fmt->version.minor = -1;
   386              return 0;
   387          }
   388          else if (memcmp(s, "BCF\2", 4) == 0) {
   389              fmt->category = variant_data;
   390              fmt->format = bcf;
   391              fmt->version.major = s[3];
   392              fmt->version.minor = (len >= 5 && s[4] <= 2)? s[4] : 0;
   393              return 0;
   394          }
   395          else if (memcmp(s, "CSI\1", 4) == 0) {
   396              fmt->category = index_file;
   397              fmt->format = csi;
   398              fmt->version.major = 1, fmt->version.minor = -1;
   399              return 0;
   400          }
   401          else if (memcmp(s, "TBI\1", 4) == 0) {
   402              fmt->category = index_file;
   403              fmt->format = tbi;
   404              return 0;
   405          }
   406      }
   407      else if (len >= 16 && memcmp(s, "##fileformat=VCF", 16) == 0) {
   408          fmt->category = variant_data;
   409          fmt->format = vcf;
   410          if (len >= 21 && s[16] == 'v')
   411              parse_version(fmt, &s[17], &s[len]);
   412          return 0;
   413      }
   414      else if (len >= 4 && s[0] == '@' &&
   415               (memcmp(s, "@HD\t", 4) == 0 || memcmp(s, "@SQ\t", 4) == 0 ||
   416                memcmp(s, "@RG\t", 4) == 0 || memcmp(s, "@PG\t", 4) == 0 ||
   417                memcmp(s, "@CO\t", 4) == 0)) {
   418          fmt->category = sequence_data;
   419          fmt->format = sam;
   420          // @HD-VN is not guaranteed to be the first tag, but then @HD is
   421          // not guaranteed to be present at all...
   422          if (len >= 9 && memcmp(s, "@HD\tVN:", 7) == 0)
   423              parse_version(fmt, &s[7], &s[len]);
   424          else
   425              fmt->version.major = 1, fmt->version.minor = -1;
   426          return 0;
   427      }
   428      else if (cmp_nonblank("{\"htsget\":", s, &s[len]) == 0) {
   429          fmt->category = unknown_category;
   430          fmt->format = htsget;
   431          return 0;
   432      }
   433      else if (len > 8 && memcmp(s, "crypt4gh", 8) == 0) {
   434          fmt->category = unknown_category;
   435          fmt->format = hts_crypt4gh_format;
   436          return 0;
   437      }
   438      else if (len >= 1 && s[0] == '>' && secondline_is_bases(s, &s[len])) {
   439          fmt->format = fasta_format;
   440          return 0;
   441      }
   442      else if (len >= 1 && s[0] == '@' && secondline_is_bases(s, &s[len])) {
   443          fmt->category = sequence_data;
   444          fmt->format = fastq_format;
   445          return 0;
   446      }
   447      else if (parse_tabbed_text(columns, sizeof columns, s,
   448                                 &s[len], &complete) > 0) {
   449          // A complete SAM line is at least 11 columns.  On unmapped long reads may
   450          // be missing two.  (On mapped long reads we must have an @ header so long
   451          // CIGAR is irrelevant.)
   452          if (colmatch(columns, "ZiZiiCZiiZZOOOOOOOOOOOOOOOOOOOO+")
   453              >= 9 + 2*complete) {
   454              fmt->category = sequence_data;
   455              fmt->format = sam;
   456              fmt->version.major = 1, fmt->version.minor = -1;
   457              return 0;
   458          }
   459          else if (fmt->compression == gzip && colmatch(columns, "iiiiii") == 6) {
   460              fmt->category = index_file;
   461              fmt->format = crai;
