  3877  static int aux_to_le(char type, uint8_t *out, const uint8_t *in, size_t len) {
  3878      int tsz = aux_type2size(type);
  3879
  3880      if (tsz >= 2 && tsz <= 8 && (len & (tsz - 1)) != 0) return -1;
  3881
  3882      switch (tsz) {
  3883          case 'H': case 'Z': case 1:  // Trivial
  3884              memcpy(out, in, len);
  3885              break;
  3886
  3887  #define aux_val_to_le(type_t, store_le) do {                            \
  3888          type_t v;                                                       \
  3889          size_t i;                                                       \
  3890          for (i = 0; i < len; i += sizeof(type_t), out += sizeof(type_t)) { \
  3891              memcpy(&v, in + i, sizeof(type_t));                         \
  3892              store_le(v, out);                                           \
  3893          }                                                               \
  3894      } while (0)
  3895
  3896          case 2: aux_val_to_le(uint16_t, u16_to_le); break;
  3897          case 4: aux_val_to_le(uint32_t, u32_to_le); break;
  3898          case 8: aux_val_to_le(uint64_t, u64_to_le); break;
  3899
  3900  #undef aux_val_to_le
  3901
  3902          case 'B': { // Recurse!
  3903              uint32_t n;
  3904              if (len < 5) return -1;
  3905              memcpy(&n, in + 1, 4);
  3906              out[0] = in[0];
  3907              u32_to_le(n, out + 1);
  3908              return aux_to_le(in[0], out + 5, in + 5, len - 5);
  3909          }
  3910
  3911          default: // Unknown type code
  3912              return -1;
  3913      }
  3914
  3915
  3916
  3917      return 0;
  3918  }
