   668  /*
   669   * Splits str into a prefix, delimiter ('\0' or delim), and suffix, writing
   670   * the prefix in lowercase into buf and returning a pointer to the suffix.
   671   * On return, buf is always NUL-terminated; thus assumes that the "keyword"
   672   * prefix should be one of several known values of maximum length buflen-2.
   673   * (If delim is not found, returns a pointer to the '\0'.)
   674   */
   675  static const char *
   676  scan_keyword(const char *str, char delim, char *buf, size_t buflen)
   677  {
   678      size_t i = 0;
   679      while (*str && *str != delim) {
   680          if (i < buflen-1) buf[i++] = tolower_c(*str);
   681          str++;
   682      }
   683
   684      buf[i] = '\0';
   685      return *str? str+1 : str;
   686  }
